CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, minecraft_username VARCHAR(32) NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')), banned BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS products (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'Ranks', description TEXT NOT NULL DEFAULT '', price INTEGER NOT NULL CHECK(price>=0), active BOOLEAN NOT NULL DEFAULT TRUE, display_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS orders (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), product_id BIGINT REFERENCES products(id) ON DELETE SET NULL, product_name TEXT NOT NULL, price INTEGER NOT NULL, utr TEXT NOT NULL, screenshot_path TEXT, status TEXT NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Approved','Rejected')), admin_notes TEXT NOT NULL DEFAULT '', processed_by BIGINT REFERENCES users(id), processed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id BIGSERIAL PRIMARY KEY, admin_id BIGINT REFERENCES users(id), action TEXT NOT NULL, target_type TEXT NOT NULL, target_id BIGINT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO products (name,category,description,price,display_order) SELECT x.name,x.category,x.description,x.price,x.ord FROM (VALUES ('Aura','Ranks','Starter rank',29,1),('MVP','Ranks','Enhanced rank',49,2),('GOD','Ranks','Powerful rank',99,3),('Elite','Ranks','Elite benefits',149,4),('Mythic','Ranks','Premium rank',199,5),('Common Key','Crate Keys','One common crate key',5,6),('Rare Key','Crate Keys','One rare crate key',15,7),('Epic Key','Crate Keys','One epic crate key',25,8),('Superior Key','Crate Keys','One superior crate key',35,9),('Common Keys ×3','Bundles','Three common keys',12,10),('Rare Keys ×4','Bundles','Four rare keys',35,11),('Epic Keys ×4','Bundles','Four epic keys',59,12),('Superior Keys ×4','Bundles','Four superior keys',79,13)) x(name,category,description,price,ord) WHERE NOT EXISTS (SELECT 1 FROM products);
